// Controlled example with state
const ControlledExample = (args: any) => {
  const [value, setValue] = useState(args.value || args.min || 0);

  return (
    <Box css={{ p: '$lg' }}>
      <Flex css={{ flexDirection: 'column', gap: '$lg', maxWidth: '400px' }}>
        <NumberField
          {...args}
          value={value}
          onChangeValue={(newValue) => {
            setValue(newValue);
            args.onChangeValue?.(newValue);
          }}
        />
        <Box>
          <Text variant="metadata" css={{ color: '$textMiddle' }}>
            Current value: <Text inline color="obolGreen">{value}</Text>
          </Text>
        </Box>
        <Flex css={{ gap: '$sm' }}>
          <Button onClick={() => setValue(args.min || 0)} color="secondary" size="sm">
            Reset to Min
          </Button>
          <Button onClick={() => setValue(args.max || 10)} color="secondary" size="sm">
            Set to Max
          </Button>
        </Flex>
      </Flex>
    </Box>
  );
};

export const Controlled: Story = {
  render: (args) => <ControlledExample {...args} />,
  args: {
    min: 1,
    max: 10,
    value: 5,
  },
  parameters: {
    docs: {
      description: {
        story: 'Controlled number field with external state management. Displays current value and provides reset buttons.',
      },
    },
  },
};

