// Boundary behavior
export const BoundaryBehavior: Story = {
  render: () => {
    const [atMin, setAtMin] = useState(0);
    const [atMax, setAtMax] = useState(10);
    const [nearMin, setNearMin] = useState(1);
    const [nearMax, setNearMax] = useState(9);

    return (
      <Box css={{ p: '$lg' }}>
        <Flex css={{ flexDirection: 'column', gap: '$3xl' }}>
          <Box>
            <Text variant="h5" css={{ mb: '$xs' }}>At Minimum (0/10)</Text>
            <Text variant="metadata" css={{ mb: '$sm', color: '$textMiddle' }}>
              Decrement button is disabled when at minimum value
            </Text>
            <NumberField min={0} max={10} value={atMin} onChangeValue={setAtMin} />
          </Box>

          <Box>
            <Text variant="h5" css={{ mb: '$xs' }}>At Maximum (10/10)</Text>
            <Text variant="metadata" css={{ mb: '$sm', color: '$textMiddle' }}>
              Increment button is disabled when at maximum value
            </Text>
            <NumberField min={0} max={10} value={atMax} onChangeValue={setAtMax} />
          </Box>

          <Box>
            <Text variant="h5" css={{ mb: '$xs' }}>Near Minimum (1/10)</Text>
            <Text variant="metadata" css={{ mb: '$sm', color: '$textMiddle' }}>
              One click away from minimum - both buttons enabled
            </Text>
            <NumberField min={0} max={10} value={nearMin} onChangeValue={setNearMin} />
          </Box>

          <Box>
            <Text variant="h5" css={{ mb: '$xs' }}>Near Maximum (9/10)</Text>
            <Text variant="metadata" css={{ mb: '$sm', color: '$textMiddle' }}>
              One click away from maximum - both buttons enabled
            </Text>
            <NumberField min={0} max={10} value={nearMax} onChangeValue={setNearMax} />
          </Box>
        </Flex>
      </Box>
    );
  },
  parameters: {
    docs: {
      description: {
        story: 'Demonstrates boundary behavior. Decrement button disables at minimum, increment button disables at maximum.',
      },
    },
  },
};

