// Form integration
export const FormIntegration: Story = {
  render: () => {
    const [quantity, setQuantity] = useState(1);
    const [age, setAge] = useState(18);

    const handleSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      alert(`Form submitted!\nQuantity: ${quantity}\nAge: ${age}`);
    };

    return (
      <Box css={{ p: '$lg', maxWidth: '500px' }}>
        <Text variant="h4" css={{ mb: '$lg' }}>Order Form</Text>
        <form onSubmit={handleSubmit}>
          <Flex css={{ flexDirection: 'column', gap: '$lg' }}>
            <Box>
              <Text variant="h5" css={{ mb: '$sm' }}>Quantity</Text>
              <NumberField
                min={1}
                max={99}
                value={quantity}
                onChangeValue={setQuantity}
                name="quantity"
              />
            </Box>

            <Box>
              <Text variant="h5" css={{ mb: '$sm' }}>Age</Text>
              <Text variant="metadata" css={{ mb: '$sm', color: '$textMiddle' }}>
                Must be 18 or older
              </Text>
              <NumberField
                min={18}
                max={120}
                value={age}
                onChangeValue={setAge}
                name="age"
              />
            </Box>

            <Button type="submit" css={{ mt: '$md' }}>
              Submit Order
            </Button>
          </Flex>
        </form>
      </Box>
    );
  },
  parameters: {
    docs: {
      description: {
        story: 'Number fields integrated in a form with name attributes for submission. Demonstrates typical use case with quantity and age inputs.',
      },
    },
  },
};

